@page "/board"
@using sv_f935948f104246f6a4403fccbd5735b6.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar">
        <span class="stat-item"><strong>Total:</strong> @_allTasks.Count</span>
        <span class="stat-item"><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span class="stat-item"><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span class="stat-item"><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="stat-item stat-overdue"><strong>Overdue:</strong> @_allTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="search-bar">
        <input type="text" placeholder="Search tasks by title..." @bind="_searchQuery" @bind:event="oninput" class="search-input" />
    </div>

    <!-- Kanban Columns -->
    <div class="kanban-board">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            <div class="kanban-column">
                <div class="column-header">
                    <h3>@column <span class="task-count">(@tasks.Count)</span></h3>
                </div>

                <div class="column-body">
                    @foreach (var task in tasks)
                    {
                        <div class="task-card">
                            <div class="task-title">@task.Title</div>
                            <div class="task-assignee">@task.Assignee</div>
                            <span class="priority-badge priority-@task.Priority.ToLower()">@task.Priority</span>
                            <div class="task-due">@task.DueDate.ToString("MMM dd")</div>
                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    <button class="btn btn-sm btn-move" @onclick="() => MoveTask(task, -1)">◀ Move Left</button>
                                }
                                @if (GetColumnIndex(column) < _columns.Length - 1)
                                {
                                    <button class="btn btn-sm btn-move" @onclick="() => MoveTask(task, 1)">Move Right ▶</button>
                                }
                            </div>
                        </div>
                    }
                </div>

                @if (_showForm.TryGetValue(column, out var show) && show)
                {
                    <div class="add-task-form">
                        <input type="text" placeholder="Title" @bind="_formData[column].Title" class="form-input" />
                        <input type="text" placeholder="Assignee" @bind="_formData[column].Assignee" class="form-input" />
                        <select @bind="_formData[column].Priority" class="form-input">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" @bind="_formData[column].DueDate" class="form-input" />
                        <div class="form-actions">
                            <button class="btn btn-save" @onclick="() => SaveTask(column)">Save</button>
                            <button class="btn btn-cancel" @onclick="() => CancelForm(column)">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-add" @onclick="() => ShowAddForm(column)">+ Add Task</button>
                }
            </div>
        }
    </div>
}

<style>
    .stats-bar {
        display: flex;
        gap: 1.5rem;
        padding: 1rem;
        background: #f8f9fa;
        border-radius: 8px;
        margin-bottom: 1rem;
        flex-wrap: wrap;
    }
    .stat-item { font-size: 0.95rem; }
    .stat-overdue { color: #dc3545; }

    .search-bar { margin-bottom: 1rem; }
    .search-input {
        width: 100%;
        max-width: 400px;
        padding: 0.5rem 0.75rem;
        border: 1px solid #dee2e6;
        border-radius: 6px;
        font-size: 0.95rem;
    }

    .kanban-board {
        display: flex;
        gap: 1rem;
        align-items: flex-start;
    }
    .kanban-column {
        flex: 1;
        background: #f1f3f5;
        border-radius: 8px;
        padding: 1rem;
        min-width: 250px;
    }
    .column-header h3 {
        margin: 0 0 0.75rem 0;
        font-size: 1.1rem;
    }
    .task-count { color: #6c757d; font-weight: normal; font-size: 0.9rem; }

    .task-card {
        background: #fff;
        border: 1px solid #dee2e6;
        border-radius: 6px;
        padding: 0.75rem;
        margin-bottom: 0.5rem;
    }
    .task-title { font-weight: 600; margin-bottom: 0.25rem; }
    .task-assignee { font-size: 0.85rem; color: #6c757d; margin-bottom: 0.25rem; }
    .task-due { font-size: 0.85rem; color: #495057; margin-top: 0.25rem; }

    .priority-badge {
        display: inline-block;
        padding: 0.15rem 0.5rem;
        border-radius: 4px;
        font-size: 0.75rem;
        font-weight: 600;
        color: #fff;
    }
    .priority-high { background-color: #dc3545; }
    .priority-medium { background-color: #ffc107; color: #212529; }
    .priority-low { background-color: #28a745; }

    .task-actions {
        margin-top: 0.5rem;
        display: flex;
        gap: 0.5rem;
    }
    .btn-move {
        font-size: 0.75rem;
        padding: 0.2rem 0.5rem;
        border: 1px solid #6c757d;
        background: #fff;
        border-radius: 4px;
        cursor: pointer;
    }
    .btn-move:hover { background: #e9ecef; }

    .btn-add {
        width: 100%;
        padding: 0.5rem;
        border: 1px dashed #adb5bd;
        background: transparent;
        border-radius: 6px;
        cursor: pointer;
        color: #6c757d;
        margin-top: 0.5rem;
    }
    .btn-add:hover { background: #e9ecef; }

    .add-task-form {
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
        margin-top: 0.5rem;
        padding: 0.75rem;
        background: #fff;
        border-radius: 6px;
        border: 1px solid #dee2e6;
    }
    .form-input {
        padding: 0.4rem 0.5rem;
        border: 1px solid #ced4da;
        border-radius: 4px;
        font-size: 0.9rem;
    }
    .form-actions { display: flex; gap: 0.5rem; }
    .btn-save {
        padding: 0.4rem 0.75rem;
        background: #0d6efd;
        color: #fff;
        border: none;
        border-radius: 4px;
        cursor: pointer;
    }
    .btn-cancel {
        padding: 0.4rem 0.75rem;
        background: #6c757d;
        color: #fff;
        border: none;
        border-radius: 4px;
        cursor: pointer;
    }
</style>

@code {
    private readonly string[] _columns = { "To Do", "In Progress", "Done" };
    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;
    private Dictionary<string, bool> _showForm = new();
    private Dictionary<string, TaskFormModel> _formData = new();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }

        foreach (var col in _columns)
        {
            _showForm[col] = false;
            _formData[col] = new TaskFormModel();
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
        => _allTasks
            .Where(t => t.Status == status &&
                        (string.IsNullOrWhiteSpace(_searchQuery) ||
                         t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)))
            .ToList();

    private int GetColumnIndex(string column)
        => Array.IndexOf(_columns, column);

    private async Task MoveTask(TaskItem task, int direction)
    {
        var currentIndex = GetColumnIndex(task.Status);
        var newIndex = currentIndex + direction;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        var newStatus = _columns[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = _allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
                _allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        _showForm[column] = true;
        _formData[column] = new TaskFormModel();
    }

    private void CancelForm(string column)
    {
        _showForm[column] = false;
    }

    private async Task SaveTask(string column)
    {
        var form = _formData[column];
        if (string.IsNullOrWhiteSpace(form.Title)) return;

        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            // The service creates it with the appropriate status based on column context,
            // but we ensure it appears in the correct column.
            var taskInColumn = newTask with { Status = column };
            _allTasks.Add(taskInColumn);
            _showForm[column] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }

    private class TaskFormModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    }
}

